import {STARTER,POINTS} from './builds.js';
export const freshProgress=()=>({version:1,revision:0,completed:[],medals:{},cup:null,build:{...STARTER},presets:[],history:[]});
export function applyResult(progress,result,cupId,round){const p=structuredClone(progress);if(p.history.includes(result.id))return p;p.history.push(result.id);p.history=p.history.slice(-500);p.revision=(p.revision||0)+1;if(result.dnf||result.mode!=='league')return p;if(!p.cup||p.cup.id!==cupId||p.cup.rounds.length!==round)return p;const event=p.cup.index*3+round+1;if(!p.completed.includes(event))p.completed.push(event);const place=result.classification.findIndex(c=>c.id==='player'),medal=place===0?3:place<3?2:1,key=event+':'+result.difficulty;p.medals[key]=Math.max(p.medals[key]||0,medal);p.cup.rounds.push(result);p.cup.pending=null;return p;}
export async function openStore(){return new Promise((resolve,reject)=>{const req=indexedDB.open('scrap-league',1);req.onupgradeneeded=()=>req.result.createObjectStore('records');req.onerror=()=>reject(req.error);req.onsuccess=()=>resolve(new Store(req.result));});}
export class Store{
 constructor(db){this.db=db;db.onversionchange=()=>db.close();}
 get(key){return new Promise((resolve,reject)=>{const tx=this.db.transaction('records'),r=tx.objectStore('records').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
 set(key,value){return this.update(key,()=>value);}
 update(key,fn){return new Promise((resolve,reject)=>{const tx=this.db.transaction('records','readwrite'),s=tx.objectStore('records'),r=s.get(key);let result;r.onsuccess=()=>{try{result=fn(r.result);s.put(result,key);}catch(e){reject(e);tx.abort();}};tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Save transaction aborted.'));});}
 async keys(prefix){return new Promise((resolve,reject)=>{const t=this.db.transaction('records'),r=t.objectStore('records').getAllKeys();r.onsuccess=()=>resolve(r.result.filter(k=>k.startsWith(prefix)));r.onerror=()=>reject(r.error);});}
 trashDraft(id,baseline){return this.update('draft:'+id,old=>{if(!old||old.revision!==baseline)throw Error('Draft changed in another tab. Reload before moving it to Trash.');return {...old,revision:old.revision+1,deletedAt:Date.now(),expiresAt:Date.now()+7*86400000};});}
 restoreDraft(id){return this.update('draft:'+id,old=>{if(!old?.deletedAt||old.expiresAt<Date.now())throw Error('This draft is outside the seven-day recovery window.');const {deletedAt,expiresAt,...rest}=old;return {...rest,revision:old.revision+1};});}
 saveDraft(track,baseline,view,tested){return this.update('draft:'+track.id,old=>{if((old?.revision||0)!==baseline)throw Error('This draft changed in another tab. Download your work or save a copy.');return{revision:baseline+1,track,view,tested,updatedAt:new Date().toISOString(),previous:old?[{track:old.track,tested:old.tested},...(old.previous||[])].slice(0,2):[]};});}
 commitResult(result,ghost,cupId,round){return new Promise((resolve,reject)=>{const tx=this.db.transaction('records','readwrite'),s=tx.objectStore('records'),existing=s.get('result:'+result.id);let progress;existing.onsuccess=()=>{const p=s.get('progress');p.onsuccess=()=>{progress=p.result||freshProgress();if(existing.result)return;progress=applyResult(progress,result,cupId,round);s.put(progress,'progress');s.put(result,'result:'+result.id);if(!result.dnf&&result.mode!=='lesson'){const best=s.get('best:'+result.key);best.onsuccess=()=>{if(!best.result||result.elapsedMs<best.result.result.elapsedMs)s.put({result,ghost},'best:'+result.key);};}};};tx.oncomplete=()=>resolve(progress);tx.onabort=tx.onerror=()=>reject(tx.error||Error('Result save failed.'));});}
}

